tool_calls:
mkdir -p /lib && cat > /lib/utils.sh <<'EOF'
#!/bin/bash
to_upper() {
  tr '[:lower:]' '[:upper:]'
}

count_lines() {
  wc -l < "$1" | tr -d '[:space:]'
}

file_size() {
  wc -c < "$1" | tr -d '[:space:]'
}
EOF
cat /lib/utils.sh
ls -l /lib/utils.sh

cat > /lib/utils.sh <<'EOF'
#!/bin/bash
to_upper() {
  tr '[:lower:]' '[:upper:]'
}

count_lines() {
  wc -l < "$1" | awk '{print $1}'
}

file_size() {
  wc -c < "$1" | awk '{print $1}'
}
EOF
cat /lib/utils.sh
echo "=== verify ==="
source /lib/utils.sh
echo 'hello world' | to_upper
count_lines /data/sample.txt
file_size /data/sample.txt
echo "=== types ==="
type to_upper; type count_lines; type file_size

